 payment_intent text,
 billing_collaborator_id uuid,
 source_tag_id uuid,
 source_rendimiento_id uuid,
 benefits_context jsonb default '{}'::jsonb,
 benefits_processed_at timestamp with time zone
);

create table public.rendimiento_llamadas (
